-- =============================================================================
-- Valorizador de Derivados: carga de datos de mercado de demostración
--
-- Generado desde datos_fx.csv, datos_curvas.csv y fechas_curvas.csv.
-- Contenido: 4266 tipos de cambio, 632 curvas y 17121 vértices,
-- del 2026-01-02 al 2026-08-25.
--
-- Se puede ejecutar más de una vez: los tipos de cambio se actualizan y las curvas
-- de las mismas fechas y códigos se reemplazan completas. No toca otras fechas.
-- Requiere el esquema en revisión 0002 (curva_vertice con la columna codigo).
--
-- Uso:
--     psql -U postgres -d valorizador -f cargar_datos_mercado.sql
-- =============================================================================

BEGIN;

-- ------------------------------------------------------------ tipos de cambio

ON CONFLICT (fecha, par) DO UPDATE SET valor = EXCLUDED.valor;

ON CONFLICT (fecha, par) DO UPDATE SET valor = EXCLUDED.valor;

ON CONFLICT (fecha, par) DO UPDATE SET valor = EXCLUDED.valor;

ON CONFLICT (fecha, par) DO UPDATE SET valor = EXCLUDED.valor;

ON CONFLICT (fecha, par) DO UPDATE SET valor = EXCLUDED.valor;


-- ---------------------------------------------------------------------- curvas

CREATE TEMP TABLE tmp_curva (
    fecha                  DATE NOT NULL,
    codigo                 VARCHAR(50) NOT NULL,
    fraccion_anio          VARCHAR(10) NOT NULL,
    factor_capitalizacion  VARCHAR(3) NOT NULL
) ON COMMIT DROP;

CREATE TEMP TABLE tmp_vertice (
    fecha       DATE NOT NULL,
    codigo      VARCHAR(50) NOT NULL,
    plazo_dias  INTEGER NOT NULL,
    tasa        DOUBLE PRECISION NOT NULL
) ON COMMIT DROP;





















-- Reemplaza las curvas de las mismas fechas y códigos. Sus vértices se borran en cascada.
DELETE FROM curva c
USING tmp_curva t
WHERE c.fecha = t.fecha AND c.codigo = t.codigo;

SELECT fecha, codigo, fraccion_anio, factor_capitalizacion
FROM tmp_curva
ORDER BY fecha, codigo;

SELECT c.id, t.codigo, t.plazo_dias, t.tasa
FROM tmp_vertice t
JOIN curva c ON c.fecha = t.fecha AND c.codigo = t.codigo
ORDER BY c.id, t.plazo_dias;

COMMIT;

-- ---------------------------------------------------------------- verificación

SELECT 'fx' AS tabla, count(*) AS filas, min(fecha) AS desde, max(fecha) AS hasta FROM fx
UNION ALL
SELECT 'curva', count(*), min(fecha), max(fecha) FROM curva
UNION ALL
SELECT 'curva_vertice', count(*), min(c.fecha), max(c.fecha)
FROM curva_vertice v JOIN curva c ON c.id = v.curva_id;
